namespace asio = boost::asio;
using tcp = asio::ip::tcp;
using Error = boost::system::error_code;

class Client : public std::enable_shared_from_this<Client> {
    tcp::resolver resolver_;
    tcp::socket socket_;
    asio::steady_timer timer_;
    std::chrono::steady_clock::time_point deadline_;
    std::string request_ = "PING\n", input_;
    bool done_ = false;
    bool success_ = false;

    void finish(Error ec, std::size_t n = 0) {
        if (done_) return;
        done_ = true;
        success_ = !ec;
        Error ignored;
        timer_.cancel(ignored);
        resolver_.cancel();
        socket_.close(ignored);
        if (ec) std::cerr << "request failed: " << ec.message() << '\n';
        else std::cout << input_.substr(0, n);
    }
    bool stop_before_next_step() {
        if (done_) return true;
        if (std::chrono::steady_clock::now() >= deadline_) {
            finish(asio::error::timed_out);
            return true;
        }
        return false;
    }
    void write_request() {
        auto self = shared_from_this();
        asio::async_write(socket_, asio::buffer(request_),
            [self](Error ec, std::size_t) {
                if (self->stop_before_next_step()) return;
                if (ec) return self->finish(ec);
                self->read_response();
            });
    }
    void read_response() {
        auto self = shared_from_this();
        asio::async_read_until(socket_, asio::dynamic_buffer(input_, 4096), '\n',
            [self](Error ec, std::size_t n) {
                if (self->stop_before_next_step()) return;
                self->finish(ec, n);
            });
    }
public:
    explicit Client(asio::io_context& io)
        : resolver_(io), socket_(io), timer_(io) {}
    bool success() const { return success_; } // main читает после run
    void start(const std::string& host, const std::string& service) {
        // В этом контракте start вызывается ровно один раз.
        deadline_ = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        timer_.expires_at(deadline_);
        auto self = shared_from_this();
        timer_.async_wait([self](Error ec) {
            if (!ec) self->finish(asio::error::timed_out);
        });
        resolver_.async_resolve(host, service,
            [self](Error ec, tcp::resolver::results_type endpoints) {
                if (self->stop_before_next_step()) return;
                if (ec) return self->finish(ec);
                asio::async_connect(self->socket_, endpoints,
                    [self](Error ec, const tcp::endpoint&) {
                        if (self->stop_before_next_step()) return;
                        if (ec) return self->finish(ec);
                        self->write_request();
                    });
            });
    }
};

int main(int argc, char** argv) {
    if (argc != 3) return 2; // host service
    try {
        asio::io_context io;
        auto client = std::make_shared<Client>(io);
        client->start(argv[1], argv[2]);
        io.run(); // единственный поток выполнения обработчиков
        return client->success() ? 0 : 1;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}

