// Эскиз последовательной Session; отмена и deadline принадлежат владельцу.
asio::awaitable<void> framed_echo(tcp::socket socket) {
    for (unsigned served = 0; served < 100; ++served) {
        std::array<unsigned char, 1> header{};
        co_await asio::async_read(socket, asio::buffer(header), asio::use_awaitable);
        const auto length = header[0];
        if (length == 0 || length > 64)
            throw std::runtime_error("invalid frame size");

        std::vector<unsigned char> body(length);
        co_await asio::async_read(socket, asio::buffer(body), asio::use_awaitable);
        std::array<asio::const_buffer, 2> response{
            asio::buffer(header), asio::buffer(body)};
        co_await asio::async_write(socket, response, asio::use_awaitable);
    }
}

