awaitable<void> run_session(tcp::socket socket, SharedDeps deps) {
  beast::tcp_stream stream(std::move(socket));
  beast::flat_buffer input;
  for (std::size_t served = 0; served < deps.max_requests; ++served) {
    http::request_parser<http::string_body> parser;
    parser.header_limit(deps.max_header);
    parser.body_limit(deps.max_body);
    stream.expires_after(deps.request_read_deadline);
    co_await http::async_read(stream, input, parser, use_awaitable);

    auto request = parser.release();
    auto response = co_await deps.app.handle(std::move(request), remaining_deadline());
    stream.expires_after(deps.write_deadline);
    bool close = response.need_eof();
    co_await http::async_write(stream, response, use_awaitable);
    if (close || !response.keep_alive()) break;
  }
  // protocol-aware graceful close; errors handled at coroutine boundary
}

