#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>
#include <utility>

static_assert(CHAR_BIT == 8);

class FrameParser {
    static constexpr std::size_t max_body = 8;
    std::array<unsigned char, 2> header_{};
    std::size_t header_used_ = 0;
    std::size_t expected_ = 0;
    std::string body_;
    bool failed_ = false;

    std::optional<std::string> complete() {
        std::string result = std::move(body_);
        body_.clear();
        header_used_ = 0;
        expected_ = 0;
        return result;
    }
public:
    std::optional<std::string> push(unsigned char byte) {
        if (failed_) throw std::runtime_error("parser failed");
        if (header_used_ < 2) {
            header_[header_used_++] = byte;
            if (header_used_ != 2) return std::nullopt;
            expected_ = (static_cast<std::size_t>(header_[0]) << 8)
                      | static_cast<std::size_t>(header_[1]);
            if (expected_ > max_body) {
                failed_ = true;
                throw std::runtime_error("frame too large");
            }
            if (expected_ == 0) return complete();
            return std::nullopt;
        }
        body_.push_back(static_cast<char>(byte));
        if (body_.size() == expected_) return complete();
        return std::nullopt;
    }
    void finish() const {
        if (failed_) throw std::runtime_error("parser failed");
        if (header_used_ != 0) throw std::runtime_error("truncated frame");
    }
};

void feed(FrameParser& parser, std::string_view chunk) {
    for (unsigned char byte : chunk) {
        if (auto message = parser.push(byte)) {
            std::cout << "frame: [" << *message << "]\n";
        }
    }
}

int main() {
    FrameParser parser;
    feed(parser, std::string_view("\x00", 1));
    feed(parser, std::string_view("\x03" "A", 2));
    feed(parser, std::string_view("BC\x00\x01" "Z", 5));
    parser.finish();
    std::cout << "clean EOF\n";
    FrameParser broken;
    feed(broken, std::string_view("\x00\x02" "A", 3));
    try {
        broken.finish();
    } catch (const std::runtime_error& error) {
        std::cout << error.what() << '\n';
    }
}

